import { useId } from "react";
import type { ChangeEvent, FormEvent, KeyboardEvent } from "react";
import "./CommandBox.css";

export type CommandReply = {
  text: string;
  isError: boolean;
};

export type CommandBoxProps = {
  value: string;
  onChange: (value: string) => void;
  onSubmit: (value: string) => void;
  placeholder?: string;
  reply?: CommandReply;
};

export function CommandBox({
  value,
  onChange,
  onSubmit,
  placeholder = "Type a command",
  reply,
}: CommandBoxProps) {
  const inputId = useId();
  const replyId = useId();

  function handleChange(event: ChangeEvent<HTMLInputElement>): void {
    onChange(event.target.value);
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>): void {
    event.preventDefault();
    const trimmed = value.trim();
    if (trimmed === "") {
      return;
    }
    onSubmit(trimmed);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLInputElement>): void {
    // Escape clears a non-empty command without leaving the field.
    if (event.key === "Escape" && value !== "") {
      event.preventDefault();
      onChange("");
    }
  }

  const replyClassName = reply?.isError
    ? "command-box__reply command-box__reply--error"
    : "command-box__reply";

  return (
    <form className="command-box" onSubmit={handleSubmit} aria-label="Command">
      <label htmlFor={inputId} className="command-box__label">
        Command
      </label>
      <input
        id={inputId}
        className="command-box__input"
        type="text"
        value={value}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        placeholder={placeholder}
        autoComplete="off"
        autoCapitalize="off"
        autoCorrect="off"
        spellCheck={false}
        aria-describedby={reply ? replyId : undefined}
      />
      {reply ? (
        <p
          id={replyId}
          className={replyClassName}
          role={reply.isError ? "alert" : "status"}
        >
          {reply.text}
        </p>
      ) : null}
    </form>
  );
}
